ValidationRule.errorConditionFormula:
AND(

    /* Record was already in Submitted status */
    ISPICKVAL(PRIORVALUE(Status__c), "Submitted"),

    /* Allow ONLY change to Approved or Rejected */
    NOT(
        OR(
            ISPICKVAL(Status__c, "Approved"),
            ISPICKVAL(Status__c, "Rejected")
        )
    )

)
